def build_agent(sandbox):
    # Vehicle configuration
    beam_w = 2.4  # Width of each beam
    beam_h = 0.6  # Height for buoyancy and ground clearance
    y_center = 0.5  # Y-position to provide 0.2m ground clearance
    density = 208.0  # Ensures total mass < 600kg

    # Position beams on the starting land zone
    centers_x = [2.0, 2.0 + beam_w]
    bodies = []
    for x in centers_x:
        b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=density)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)

    # Connect beams rigidly in the center
    anchor_x = (centers_x[0] + centers_x[1]) / 2
    sandbox.add_joint(bodies[0], bodies[1], (anchor_x, y_center), type='rigid')

    return bodies[-1]  # Return the rear beam for thrust control


def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x()
    target_x = 26.0

    # Stop if we've reached the target
    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Apply thrust only every 200 steps
    if step_count % 200 != 0:
        return

    THRUST_F = 520.0
    bodies = sandbox.bodies

    on_land = front_x < 10.0
    in_water = front_x >= 10.0
    in_deep_channel = 16.5 <= front_x <= 19.5

    if on_land:
        # Apply full horizontal thrust to both beams
        for b in bodies:
            if b.active:
                vx = b.linearVelocity.x
                if vx > 1.8:
                    fx = THRUST_F * 0.1
                elif vx > 1.0:
                    fx = THRUST_F * 0.4
                else:
                    fx = THRUST_F
                sandbox.apply_force(b, fx, 0.0, step_count=step_count)
    elif in_water:
        # Thrust to the rear beam
        if len(bodies) > 1 and bodies[-1].active:
            rear_beam = bodies[-1]
            vx = rear_beam.linearVelocity.x
            if vx > 1.8:
                fx_scale = 0.1
            elif vx > 1.0:
                fx_scale = 0.4
            else:
                fx_scale = 1.0
            fx = THRUST_F * fx_scale
            if in_deep_channel:
                # Apply upward force to counter reduced buoyancy
                fy = 0.3 * THRUST_F
            else:
                fy = 0.1 * THRUST_F
            sandbox.apply_force(rear_beam, fx, fy, step_count=step_count)

